// 1. Declare a delegate type
public delegate void LogHandler(string message);

public class Logger
{
    // 2. Method matching the delegate signature
    public void LogToConsole(string message)
    {
        Console.WriteLine($"[Console] {message}");
    }

    public void LogToFile(string message)
    {
        File.AppendAllText("log.txt", $"{DateTime.Now}: {message}\n");
    }
}

// 3. Usage
var logger = new Logger();
LogHandler handler = logger.LogToConsole;
handler("Hello from delegate!");

// Assign a different method
handler = logger.LogToFile;
handler("Hello from file!");

LogHandler handler = logger.LogToConsole;
handler += logger.LogToFile;

// Both methods run
handler("Important event!");

// Remove one
handler -= logger.LogToConsole;
handler("Only file now");

// Action: no return value
Action<string> log = Console.WriteLine;
log("Hello, Action!");

// Func: returns a value
Func<int, int, int> add = (a, b) => a + b;
Console.WriteLine(add(3, 5)); // 8

// Predicate: returns bool
Predicate<int> isEven = n => n % 2 == 0;
Console.WriteLine(isEven(4)); // True

// 1. Delegate type for the event
public delegate void ClickHandler(object sender, EventArgs e);

// 2. Publisher class
public class Button
{
    // Event based on the delegate
    public event ClickHandler Clicked;

    public void Press()
    {
        // Raise the event
        Clicked?.Invoke(this, EventArgs.Empty);
    }
}

// 3. Subscriber class
public class Form
{
    private Button _button;

    public Form()
    {
        _button = new Button();
        _button.Clicked += OnButtonClicked;
    }

    private void OnButtonClicked(object sender, EventArgs e)
    {
        Console.WriteLine("Button was pressed!");
    }
}

// 4. Usage
var form = new Form();
form.ShowAndPress(); // Output: Button was pressed!

// 1. Custom event arguments
public class MessageEventArgs : EventArgs
{
    public string Message { get; set; }
    public DateTime Timestamp { get; set; } = DateTime.Now;
}

// 2. Publisher
public class Notifier
{
    // Standard event pattern
    public event EventHandler<MessageEventArgs> MessageReceived;

    public void Send(string message)
    {
        var args = new MessageEventArgs { Message = message };
        MessageReceived?.Invoke(this, args);
    }
}

// 3. Subscriber
public class Listener
{
    public void Subscribe(Notifier notifier)
    {
        notifier.MessageReceived += (sender, args) =>
        {
            Console.WriteLine($"[{args.Timestamp}] {args.Message}");
        };
    }
}

public class StockTicker
{
    public event EventHandler<PriceChangedEventArgs> PriceChanged;

    private decimal _price;
    public decimal Price
    {
        get => _price;
        set
        {
            if (_price != value)
            {
                _price = value;
                OnPriceChanged(new PriceChangedEventArgs { NewPrice = _price });
            }
        }
    }

    protected virtual void OnPriceChanged(PriceChangedEventArgs e)
    {
        PriceChanged?.Invoke(this, e);
    }
}

public class PriceChangedEventArgs : EventArgs
{
    public decimal NewPrice { get; set; }
}

// Usage
var ticker = new StockTicker();
ticker.PriceChanged += (s, e) =>
    Console.WriteLine($"New price: {e.NewPrice:C}");

ticker.Price = 150.00m; // Triggers event

public class App : IDisposable
{
    private readonly Notifier _notifier;

    public App(Notifier notifier)
    {
        _notifier = notifier;
        _notifier.MessageReceived += OnMessage;
    }

    private void OnMessage(object sender, EventArgs e)
    {
        Console.WriteLine("Message received");
    }

    public void Dispose()
    {
        _notifier.MessageReceived -= OnMessage;
    }
}
